export interface ModelOffer {
  name: ModelName;
  max_concurrent: number;
  max_tokens: number;
}

export interface HeartbeatFrame {
  type: "heartbeat";
  load: {
    [k: string]: number;
  };
}

export interface CompletionFrame {
  type: "completion";
  job_id: string;
  text: string;
  usage_reported?: Usage;
}

export interface Usage {
  prompt_tokens: number;
  completion_tokens: number;
}

export interface ErrorFrame {
  type: "error";
  job_id: string;
  code: "model_unavailable" | "timeout" | "internal";
  message: string;
}

export interface GoodbyeFrame {
  type: "goodbye";
  reason: "schedule" | "shutdown";
}

export interface WelcomeFrame {
  type: "welcome";
  thinker: ThinkerName;
  accepted_models: ModelName[];
  server_time: string;
}

export interface JobFrame {
  type: "job";
  job_id: string;
  model: ModelName;
  /**
   * @minItems 1
   * @maxItems 64
   */
  messages: [Message, ...Message[]];
  max_tokens: number;
  temperature: number;
  stop: string[] | null;
  deadline: string;
  cache_hint?: CacheHint;
  /**
   * Constrained output (decision 0049). The serialized schema is at most 64 KiB (MAX_RESPONSE_FORMAT_BYTES, checked by validateThinkerFrame). A Thinker that does not support it ignores it; the Mind validates the output regardless.
   */
  response_format?: {
    type: "json_schema";
    schema: {
      [k: string]: unknown;
    };
  };
  /**
   * Whether the model may think before answering (decision 0049). A Thinker without the switch ignores it.
   */
  reasoning?: "off" | "on";
}

export interface Message {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface CacheHint {
  stable_prefix_chars: number;
}

export interface CancelFrame {
  type: "cancel";
  job_id: string;
}

export interface DrainFrame {
  type: "drain";
  reconnect_after_seconds: number;
}

export interface ThoughtEventPayload {
  thought_id: string;
  wake_reason: string;
  outcome: "planned" | "fallback_continue" | "fallback_hold" | "tired" | "model_error" | "invalid_output";
  latency_ms: number;
  /**
   * The pinned model configuration the thought ran on (weights, quantisation, sampling, runtime).
   */
  model_config: string;
  effort: string;
  /**
   * The intent the thought started, or null.
   */
  intent_id: string | null;
}

export type Action =
  | {
      do: "goto";
      /**
       * A position, or the name of an agent.
       */
      target: Position | string;
    }
  | {
      do: "mine";
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      block: string;
      count: number;
    }
  | {
      do: "craft";
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      item: string;
      count: number;
    }
  | {
      do: "place";
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      block: string;
      /**
       * A position, or feet for the block under the agent.
       */
      at: Position | "feet";
    }
  | {
      do: "build";
      blueprint: {
        name: string;
        /**
         * @maxItems 512
         */
        blocks: {
          /**
           * An item ID without its namespace prefix, such as iron_ingot.
           */
          block: string;
          dx: number;
          dy: number;
          dz: number;
        }[];
      };
    }
  | {
      do: "attack";
      target: string;
    }
  | {
      do: "eat";
    }
  | {
      do: "sleep";
    }
  | {
      do: "unstick";
    }
  | {
      do: "give";
      to: string;
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      item: string;
      count: number;
    }
  | {
      do: "write_sign";
      text: string;
    }
  | ((
      | {
          skill_id: unknown;
          [k: string]: unknown;
        }
      | {
          text: unknown;
          [k: string]: unknown;
        }
    ) & {
      do: "write_book";
      title: string;
      skill_id?: string;
      text?: string;
    })
  | {
      do: "read_book";
    }
  | {
      do: "use_skill";
      name: string;
      /**
       * Skill arguments. The shape depends on the skill.
       */
      args: {
        [k: string]: unknown;
      };
    }
  | {
      do: "define_skill";
      name: string;
      description: string;
      code: string;
    }
  | {
      do: "offer";
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      item: string;
      count: number;
    }
  | {
      do: "propose";
      rule: string;
      /**
       * The proposed value. Any JSON value; the rule decides what is valid.
       */
      value:
        | {
            [k: string]: unknown;
          }
        | unknown[]
        | string
        | number
        | boolean
        | null;
      reason: string;
    }
  | {
      do: "vote";
      proposal_id: string;
      vote: "yes" | "no";
    }
  | {
      do: "note";
      text: string;
    }
  | {
      do: "wait";
      seconds: number;
    }
  | {
      do: "open";
      at: Position;
    }
  | {
      do: "deposit";
      at: Position;
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      item: string;
      count: number;
    }
  | {
      do: "withdraw";
      at: Position;
      /**
       * An item ID without its namespace prefix, such as iron_ingot.
       */
      item: string;
      count: number;
    };

export interface WakePayload {
  reason: string;
  /**
   * World age when the wake was decided.
   */
  tick: number;
  /**
   * The intent the wake concerns, or null.
   */
  intent_id: string | null;
  detail?: string;
}
